/* ===== إعدادات الطابعة ===== */
var HEADS=[[384,'2 إنش (58 مم) — 384 نقطة'],[576,'3 إنش (80 مم) — 576 نقطة'],[832,'4 إنش (110 مم) — 832 نقطة']];
