  x.fillStyle='#fff';x.fillRect(0,0,W,H);x.fillStyle='#000';x.lineWidth=4;x.strokeRect(6,6,W-12,H-12);x.textAlign='center';x.direction='rtl';x.textBaseline='middle';
  x.font="700 40px 'IBM Plex Sans Arabic',Tahoma,Arial";x.fillText('EMD Business',W/2,H*0.32);x.font="600 26px 'IBM Plex Sans Arabic',Tahoma,Arial";x.fillText('طباعة تجريبية ✓',W/2,H*0.6);
